@Path("/resolveSessions") @POST @Consumes(MediaType.APPLICATION_JSON) @Produces(MediaType.APPLICATION_JSON) public Response resolveSessions(RulePolicyRepresentation policy){
  try {
    return Response.ok(getContainer(policy).getKieSessionNamesInKieBase(policy.getModuleName())).build();
  } catch (NullPointerException e) {
    return Response.status(Response.Status.BAD_REQUEST).entity("Policy object is null").build();
  } catch (IllegalArgumentException e) {
    return Response.status(Response.Status.BAD_REQUEST).entity("Invalid module name").build();
  }
}
